9	/// `/vault` — the epic's one lock screen, shown whenever
10	/// `VaultRepository.currentStatus` isn't `VaultStatus.unlocked`
11	/// (`core/navigation/app_router.dart`'s `_redirect`). Auto-triggers the OS
12	/// biometric prompt once in [initState]; a successful
13	/// [VaultRepository.authenticate] call flips `currentStatus` to `unlocked`,
14	/// which — via `statusStream`/`refreshListenable` — re-runs the redirect and
15	/// navigates away from here on its own, so this widget never navigates
16	/// imperatively itself.
17	///
18	/// Story 2.2: every biometric failure (decline/cancel/any OS lockout — the
19	/// generic `authenticate()` catches already cover it, spec-2-2) falls
20	/// through to a real [PinKeypad] + error band, never a second biometric
21	/// "Tentar novamente" affordance (AC2). The "Usar PIN" ghost link reaches
22	/// the same keypad directly, with no error band, before any biometric
23	/// failure has happened. [VaultRepository.submitPin]'s own success emits
24	/// `VaultStatus.unlocked`, same as [VaultRepository.authenticate] — this
25	/// widget navigates away on that exactly the same way, with no branch for
26	/// "which path unlocked it".
27	class VaultLockScreen extends StatefulWidget {
28	  const VaultLockScreen({required this.vaultRepository, super.key});
29	
30	  final VaultRepository vaultRepository;
31	
32	  @override
33	  State<VaultLockScreen> createState() => _VaultLockScreenState();
34	}
35	
36	class _VaultLockScreenState extends State<VaultLockScreen> {
37	  static const _biometricFailureMessage =
38	      'Não foi possível reconhecer — digite seu PIN';
39	
40	  /// No specific copy is given anywhere in `docs/input/` for a PIN
41	  /// mismatch (the I/O matrix only specifies the `Failure` returned) —
42	  /// decided here (Design Notes), mirroring the biometric failure band's
43	  /// own tone.
44	  static const _pinMismatchMessage = 'PIN incorreto. Tente novamente.';
45	
46	  bool _authenticating = false;
47	  bool _showPinKeypad = false;
48	  String? _errorMessage;
49	
50	  @override
51	  void initState() {
52	    super.initState();
53	    _attemptAuthenticate();
54	  }
55	
56	  Future<void> _attemptAuthenticate() async {
57	    if (_authenticating) {
58	      return;
59	    }
60	    setState(() => _authenticating = true);
61	
62	    final result = await widget.vaultRepository.authenticate();
63	    if (!mounted) {
64	      return;
65	    }
66	
67	    // On success, `currentStatus` is already `unlocked` and the router's
68	    // own `refreshListenable` will navigate away from `/vault` on its own —
69	    // this widget has nothing further to do (and may already be in the
70	    // process of being disposed by the time that happens).
71	    var shouldAnnounceFailure = false;
72	    result.match(
73	      (_) {
74	        // If the user already reached the keypad manually (via "Usar
75	        // PIN") before this pending call resolved, this late failure must
76	        // never clobber whatever the keypad is currently showing — AC2's
77	        // "no second biometric-retry affordance" only concerns the
78	        // biometric view itself, which is no longer on screen.
79	        final alreadyOnKeypad = _showPinKeypad;
80	        shouldAnnounceFailure = !alreadyOnKeypad;
81	        setState(() {
82	          _authenticating = false;
83	          if (!alreadyOnKeypad) {
84	            _showPinKeypad = true;
85	            _errorMessage = _biometricFailureMessage;
86	          }
87	        });
88	      },
89	      (_) => setState(() => _authenticating = false),
90	    );
91	
92	    // `Semantics(liveRegion: true)` below is primarily honored by Android's
93	    // TalkBack; this app is iOS-only, where VoiceOver doesn't reliably treat
94	    // a live-region subtree update as an announcement. `sendAnnouncement()`
95	    // is honored on both platforms, so the biometric->PIN transition is
96	    // still spoken even if the live-region flag alone isn't.
97	    if (shouldAnnounceFailure && mounted) {
98	      await _announce(_biometricFailureMessage);
99	    }
100	  }
101	
102	  void _useManualPin() {
103	    setState(() {
104	      _showPinKeypad = true;
105	      _errorMessage = null;
106	    });
107	  }
108	
109	  Future<void> _submitPin(String pin) async {
110	    final result = await widget.vaultRepository.submitPin(pin);
111	    if (!mounted) {
112	      return;
113	    }
114	    if (result.isLeft()) {
115	      // Mismatch: stays locked, no attempt cap — the keypad itself has
116	      // already cleared its own buffer by the time this runs (PinKeypad's
117	      // own contract), so the user can simply try again.
118	      setState(() => _errorMessage = _pinMismatchMessage);
119	      await _announce(_pinMismatchMessage);
120	    }
121	    // On a match (first-use or later), `currentStatus` is already
122	    // `unlocked` and the router navigates away on its own, same as a
123	    // successful `authenticate()`.
124	  }
125	
126	  Future<void> _announce(String message) async {
127	    if (!mounted) {
128	      return;
129	    }
130	    await SemanticsService.sendAnnouncement(
131	      View.of(context),
132	      message,
133	      TextDirection.ltr,
134	    );
135	  }
136	
137	  @override
138	  Widget build(BuildContext context) {
139	    return Scaffold(
140	      backgroundColor: DesignTokens.colorSurfaceBg,
141	      body: Center(
142	        child: Padding(
143	          padding: DesignTokens.screenPadding,
144	          // `liveRegion: true` so a screen reader announces the subtree's
145	          // content whenever it changes — in particular the
146	          // biometric-view -> PIN-keypad transition below.
147	          child: Semantics(
148	            liveRegion: true,
149	            child: _showPinKeypad
150	                ? _PinView(
151	                    errorMessage: _errorMessage,
152	                    onSubmit: _submitPin,
153	                  )
154	                : _BiometricView(onUsePin: _useManualPin),
155	          ),
156	        ),
157	      ),
158	    );
159	  }
160	}
