import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

import 'package:cerne/features/vault/presentation/widgets/pin_keypad.dart';

Widget _wrap(Widget child) {
  return MaterialApp(home: Material(child: Center(child: child)));
}

Future<void> _tapDigit(WidgetTester tester, String digit) async {
  await tester.tap(find.text(digit));
  await tester.pump();
}

void main() {
  testWidgets('backspace during the 350ms auto-advance window', (
    tester,
  ) async {
    final submitted = <String>[];
    await tester.pumpWidget(_wrap(PinKeypad(onSubmit: submitted.add)));

    await _tapDigit(tester, '1');
    await _tapDigit(tester, '2');
    await _tapDigit(tester, '3');
    await _tapDigit(tester, '4'); // 4th digit -> schedules submit of '1234'

    // Within the 350ms window, user notices a typo and backspaces.
    await tester.pump(const Duration(milliseconds: 100));
    await tester.tap(find.byIcon(Icons.backspace_outlined));
    await tester.pump();

    // Let the originally-scheduled timer fire.
    await tester.pump(const Duration(milliseconds: 300));

    print('submitted so far: $submitted');
    // What does the user see on screen now?
  });
}

