5	/// The three button variants named in prototype-extract.md §6's component
6	/// table: primary (filled), secondary (outline), text (ghost).
7	enum AppButtonVariant { primary, secondaryOutline, textGhost }
8	
9	/// Shared button primitive consumed by every feature's `presentation/`
10	/// (Story 1.3 login/signup, Story 1.5 overlay, Story 1.6 nav shell).
11	///
12	/// Disabled state is identical across all three variants, per the
13	/// project-wide rule: `colorBorder` background + `colorTextSecondary`
14	/// text, never a dimmed-opacity look.
15	class AppButton extends StatelessWidget {
16	  const AppButton({
17	    super.key,
18	    required this.label,
19	    required this.onPressed,
20	    this.variant = AppButtonVariant.primary,
21	    this.textColor,
22	  });
23	
24	  /// Button label. Rendered with no `maxLines`/`overflow` clamp so it
25	  /// wraps rather than clips or truncates under Dynamic Type.
26	  final String label;
27	
28	  /// Null disables the button and switches it to the disabled visual
29	  /// state (see class doc).
30	  final VoidCallback? onPressed;
31	
32	  final AppButtonVariant variant;
33	
34	  /// Only consulted for [AppButtonVariant.textGhost]: the component table
35	  /// allows ghost buttons to use either `colorPrimary` or
36	  /// `colorTextSecondary` depending on context (e.g. "Fechar"/"Limpar").
37	  /// Defaults to `colorPrimary`.
38	  final Color? textColor;
39	
40	  @override
41	  Widget build(BuildContext context) {
42	    final Widget child = Text(
43	      label,
44	      textAlign: TextAlign.center,
45	      style: DesignTokens.textLabelMd,
46	    );
47	
48	    final ButtonStyle baseStyle = ButtonStyle(
49	      padding: const WidgetStatePropertyAll(DesignTokens.buttonPadding),
50	      shape: const WidgetStatePropertyAll(
51	        RoundedRectangleBorder(
52	          borderRadius: BorderRadius.all(
53	            Radius.circular(DesignTokens.radiusSm),
54	          ),
55	        ),
56	      ),
57	      elevation: const WidgetStatePropertyAll(0),
58	    );
59	
60	    switch (variant) {
61	      case AppButtonVariant.primary:
62	        return ElevatedButton(
63	          onPressed: onPressed,
64	          style: baseStyle.copyWith(
65	            backgroundColor: WidgetStateProperty.resolveWith((states) {
66	              if (states.contains(WidgetState.disabled)) {
67	                return DesignTokens.colorBorder;
68	              }
69	              return DesignTokens.colorPrimary;
70	            }),
71	            foregroundColor: WidgetStateProperty.resolveWith((states) {
72	              if (states.contains(WidgetState.disabled)) {
73	                return DesignTokens.colorTextSecondary;
74	              }
75	              return DesignTokens.colorOnPrimary;
76	            }),
77	            overlayColor: WidgetStateProperty.resolveWith((states) {
78	              if (states.contains(WidgetState.pressed)) {
79	                return DesignTokens.colorPrimaryPressed;
80	              }
81	              return Colors.transparent;
82	            }),
83	          ),
84	          child: child,
85	        );
86	
87	      case AppButtonVariant.secondaryOutline:
88	        return OutlinedButton(
89	          onPressed: onPressed,
90	          style: baseStyle.copyWith(
91	            backgroundColor: WidgetStateProperty.resolveWith((states) {
92	              if (states.contains(WidgetState.disabled)) {
93	                return DesignTokens.colorBorder;
94	              }
95	              return Colors.transparent;
96	            }),
97	            foregroundColor: WidgetStateProperty.resolveWith((states) {
98	              if (states.contains(WidgetState.disabled)) {
99	                return DesignTokens.colorTextSecondary;
100	              }
101	              return DesignTokens.colorPrimary;
102	            }),
103	            side: WidgetStateProperty.resolveWith((states) {
104	              if (states.contains(WidgetState.disabled)) {
105	                return const BorderSide(
106	                  color: DesignTokens.colorBorder,
107	                  width: DesignTokens.borderWidthDefault,
108	                );
109	              }
110	              return const BorderSide(
111	                color: DesignTokens.colorPrimary,
112	                width: DesignTokens.borderWidthDefault,
113	              );
114	            }),
115	          ),
116	          child: child,
117	        );
118	
119	      case AppButtonVariant.textGhost:
120	        return TextButton(
121	          onPressed: onPressed,
122	          style: baseStyle.copyWith(
123	            backgroundColor: WidgetStateProperty.resolveWith((states) {
124	              if (states.contains(WidgetState.disabled)) {
125	                return DesignTokens.colorBorder;
126	              }
127	              return Colors.transparent;
128	            }),
129	            foregroundColor: WidgetStateProperty.resolveWith((states) {
130	              if (states.contains(WidgetState.disabled)) {
131	                return DesignTokens.colorTextSecondary;
132	              }
133	              return textColor ?? DesignTokens.colorPrimary;
134	            }),
135	          ),
136	          child: child,
137	        );
138	    }
139	  }
140	}
